export function GeneratedContent({
  content = "{{content}}",
  contentType = "{{contentType}}",
  accent = "{{accent}}",
  showProvenance = {{showProvenance}},
}) {
  const bodyStyle = {
    code: { fontFamily: "ui-monospace, SFMono-Regular, Menlo, monospace", fontSize: 13, background: "#24143010", padding: 12, borderRadius: 8, whiteSpace: "pre-wrap", margin: 0 },
    summary: { fontStyle: "italic", paddingLeft: 12, borderLeft: `3px solid ${accent}`, margin: 0 },
    text: { margin: 0 },
  }[contentType] ?? { margin: 0 };
  return (
    <div style={{ maxWidth: 520, padding: "16px 18px", borderRadius: 12, background: "#FAF7F2", color: "#241430", border: "1px solid #24143020", boxSizing: "border-box", font: "15px/1.55 system-ui, sans-serif" }}>
      {showProvenance && (
        <div style={{ display: "inline-flex", alignItems: "center", gap: 6, fontSize: 11, fontWeight: 700, textTransform: "uppercase", letterSpacing: ".05em", color: accent, marginBottom: 10 }}>
          <span aria-hidden="true" style={{ width: 6, height: 6, borderRadius: "50%", background: accent, flex: "none" }} />
          Generated by AI
        </div>
      )}
      <div style={{ fontSize: 11, fontWeight: 600, textTransform: "uppercase", letterSpacing: ".05em", color: "#24143080", marginBottom: 6 }}>{contentType}</div>
      <div style={bodyStyle}>{content}</div>
    </div>
  );
}
